inline flight::Array<flight::String> collect_spine_serialize_warnings(flight::Ref<ParticleEmitterConfig> config) {
  flight::Array<flight::String> warnings = flight::Array<flight::String>{};
  if ((config->burst_count > 0.0)) {
    warnings.push(flight::String("Emission bursts are not supported by the Spine particle format and were ignored"));
  }
  if ((((config->color_end_variance_r != 0.0) || (config->color_end_variance_g != 0.0)) || (config->color_end_variance_b != 0.0))) {
    warnings.push(flight::String("colorEndVariance is not supported by the Spine format and was ignored"));
  }
  if ((((config->color_start_variance_r != 0.0) || (config->color_start_variance_g != 0.0)) || (config->color_start_variance_b != 0.0))) {
    warnings.push(flight::String("colorStartVariance is not supported by the Spine format and was ignored"));
  }
  if ((config->velocity_inheritance != 0.0)) {
    warnings.push(flight::String("velocityInheritance is not supported by the Spine format and was ignored"));
  }
  return warnings;
}


